<template><view class="page">
<view class="row heading"><view><view class="title">登科喵备考计划</view><view class="muted">科学规划 · 高效备考 · 陪你上岸</view></view><button class="share" @click="sharing=true">分享 ↗</button></view>
<view v-if="localMode" class="notice">本地体验版 · 数据保存在当前设备，支付尚未开放</view>
<view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载你的计划…</view>
<template v-else>
<view class="countdown"><image class="hero-cat" src="/static/dengkemiao.png" mode="aspectFit"/><view class="hero-copy"><text v-if="plan">距离 {{plan.examName}}</text><view v-if="plan" class="days">{{plan.remainingDays}}<text> 天</text></view><view v-else class="hero-title">有计划 · 更上岸</view><view class="countdown-note">{{plan?plan.examDate+' · 每天'+plan.dailyMinutes+'分钟':'让努力更有方向'}}</view><button class="countdown-button" @click="plan?tab('plan'):create()">{{plan?'查看我的计划':'开始备考'}} →</button></view></view>
<view class="shortcuts"><view @click="create()"><view class="shortcut-icon">✎</view><text>创建考试</text></view><view @click="tab('plan')"><view class="shortcut-icon cyan">▤</view><text>我的计划</text></view><view @click="tab('task')"><view class="shortcut-icon orange">✓</view><text>今日任务</text></view><view @click="record"><view class="shortcut-icon green">▥</view><text>学习记录</text></view></view>
<view v-if="plan" class="section row"><text>今日学习</text><text class="link" @click="tab('task')">全部任务 →</text></view><view v-if="plan" class="card"><view class="row"><view><text class="big">{{done}}</text><text class="muted"> / {{tasks.length}} 项</text></view><text class="badge">{{tasks.reduce((a,t)=>a+t.duration,0)}} 分钟</text></view><view class="progress"><view class="fill" :style="{width:(tasks.length?done*100/tasks.length:0)+'%'}"/></view><view v-if="!tasks.length" class="muted">{{plan.remainingDays===0?'考试日已到，祝你从容发挥！':'今日暂无学习任务'}}</view><view v-for="t in tasks.slice(0,3)" :key="t.id" class="task-row" @click="tab('task')"><view><text class="task-subject">{{t.subject}}</text><view class="muted">{{t.name}}</view></view><text :class="t.completed?'completed':'muted'">{{t.completed?'已完成':t.duration+' 分钟'}}</text></view></view>
<view class="section row"><text>热门考试</text><text class="link" @click="create()">更多 ›</text></view><view class="exam-grid"><view v-for="(t,i) in templates.slice(0,4)" :key="t.code" :class="['exam-item','exam-'+i]" @click="create(t.code)"><view class="exam-symbol">{{t.symbol||t.name.slice(0,1)}}</view><view class="exam-copy"><view>{{t.name}}</view><view class="muted">{{['研究生入学考试','国家 / 地方公务员','教师资格考试','CET 四级 / 六级'][i]}}</view></view></view></view><view class="encourage">每一个认真学习的今天，都算数。</view>
</template><ShareSheet :visible="sharing" @close="sharing=false"/>
</view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow,onShareAppMessage,onShareTimeline} from '@dcloudio/uni-app';import {api,current,localMode} from '../../api';import ShareSheet from '../../components/ShareSheet.vue'
const plan=ref(null),tasks=ref([]),templates=ref([]),loading=ref(true),error=ref(''),sharing=ref(false);const done=computed(()=>tasks.value.filter(t=>t.completed).length)
async function load(){loading.value=true;error.value='';try{templates.value=await api.templates();plan.value=await current();tasks.value=plan.value?await api.tasks(plan.value.id):[]}catch(e){error.value=e.message}finally{loading.value=false}}
onShow(()=>{
  // #ifdef MP-WEIXIN
  uni.showShareMenu({withShareTicket:true,menus:['shareAppMessage','shareTimeline']})
  // #endif
  load()
});onShareAppMessage(()=>({title:'登科喵 · 给努力一份清晰的计划',path:'/pages/index/index'}));onShareTimeline(()=>({title:'登科喵备考计划 · 每天进步一点点'}))
function tab(name){uni.switchTab({url:'/pages/'+name+'/index'})}function create(code=''){uni.navigateTo({url:'/pages/exam/create?type='+code})}function record(){uni.navigateTo({url:'/pages/record/index'})}
</script>

<style scoped>
.page{padding:20rpx 28rpx 40rpx}.heading{margin:4rpx 0 24rpx}.heading .title{font-size:35rpx}.heading .muted{font-size:22rpx;color:#6F8DB1}.share{color:#1677FF;background:#EAF4FF;padding:10rpx 16rpx;font-size:22rpx}.notice{font-size:20rpx;padding:10rpx 18rpx;margin-bottom:18rpx}.countdown{position:relative;overflow:hidden;background:linear-gradient(140deg,#79BDFF 0%,#258CFF 55%,#0870FF 100%);color:white;border-radius:24rpx;padding:28rpx;margin-bottom:20rpx;min-height:240rpx;box-shadow:0 10rpx 24rpx #1677FF20}.countdown::before{content:'';position:absolute;width:240rpx;height:240rpx;border:40rpx solid #ffffff10;border-radius:50%;right:-50rpx;top:-80rpx}.hero-cat{position:absolute;width:210rpx;height:210rpx;right:18rpx;bottom:18rpx;border-radius:50%}.hero-copy{position:relative;width:64%;z-index:1}.hero-title{font-size:40rpx;font-weight:800;margin-bottom:8rpx;white-space:nowrap}.days{font-size:86rpx;font-weight:800;line-height:1.3;letter-spacing:-3rpx}.days text{font-size:28rpx;font-weight:400;letter-spacing:0}.countdown-note{color:#E3F2FF;font-size:22rpx}.countdown-button{margin-top:22rpx;background:white;color:#126AE8;font-weight:700;border-radius:50rpx;width:230rpx;padding:10rpx 18rpx;font-size:24rpx}.shortcuts{display:flex;justify-content:space-around;background:white;border-radius:22rpx;padding:24rpx 8rpx;margin:20rpx 0 30rpx;font-size:22rpx;text-align:center;box-shadow:0 6rpx 24rpx #1C4B8608}.shortcut-icon{background:linear-gradient(140deg,#85C4FF,#358EFF);color:white;width:80rpx;height:80rpx;border-radius:20rpx;font-size:38rpx;line-height:80rpx;margin:0 auto 12rpx;box-shadow:inset 0 2rpx 8rpx #ffffff55}.cyan{background:linear-gradient(140deg,#70DCF0,#1DAAE0)}.green{background:linear-gradient(140deg,#8CE6CD,#21C7AA)}.orange{background:linear-gradient(140deg,#FFDA86,#FFA93B)}.task-row{display:flex;justify-content:space-between;align-items:center;padding:22rpx 0;border-bottom:1rpx solid #EDF1F7}.task-row:last-child{border:0;padding-bottom:0}.task-subject{font-weight:650}.completed{color:#20A968;font-size:24rpx}.exam-grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx}.exam-item{display:flex;align-items:center;gap:16rpx;background:linear-gradient(120deg,#F3F6FF,#EEF7FF);border-radius:20rpx;padding:24rpx 18rpx;font-size:26rpx;font-weight:650}.exam-copy .muted{font-weight:400;margin-top:4rpx;font-size:18rpx;white-space:nowrap}.exam-symbol{color:#1677FF;width:56rpx;height:56rpx;flex-shrink:0;text-align:center;line-height:56rpx;font-weight:800;font-size:32rpx}.exam-2{background:#FFFAF0}.exam-2 .exam-symbol{color:#FFAD24}.exam-3{background:#EDF9F8}.exam-3 .exam-symbol{color:#11BCAF}.encourage{text-align:center;color:#93A4BB;font-size:22rpx;margin-top:34rpx}
</style>

